using Godot;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class ActorInspectorOperations
{
    private readonly FogControlOperations _fogControls=new();private readonly FogPainterOperations _fogPainter=new();
    public bool add_special_object_value(Control inspector,Resource actor,Resource data,Resource definition,Resource property,VBoxContainer parent)
    {
        var options=property.Get("options").AsGodotDictionary();var key=property.Get("id").AsStringName();var model=Ui<RefCounted>(inspector,"model");var updaters=inspector.Get("_updaters").AsGodotArray();if(options.GetValueOrDefault("fog_actor_link",false).AsBool()){add_label(parent,property.Get("label").AsString());var choose=new OptionButton{FitToLongestItem=false,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};parent.AddChild(choose);choose.AddItem("Fog actor / local source");choose.SetItemMetadata(0,"");foreach(var value in model.Get("actors").AsGodotArray()){var candidate=value.As<Resource>();if(candidate==actor||candidate.Get("values").AsGodotDictionary().GetValueOrDefault("position").VariantType!=Variant.Type.Vector3)continue;choose.AddItem(candidate.Get("display_name").AsString());choose.SetItemMetadata(choose.ItemCount-1,candidate.Get("id"));}string current=_data.object_get_value(data,key,"").ToString();var links=actor.Get("values").AsGodotDictionary().GetValueOrDefault("fog_motion_links",new Settings()).AsGodotDictionary();current=links.GetValueOrDefault(current,current).ToString();for(int i=0;i<choose.ItemCount;i++)if(choose.GetItemMetadata(i).ToString()==current)choose.Select(i);choose.ItemSelected+=index=>{string original=_data.object_get_value(data,key,"").ToString();var next=actor.Get("values").AsGodotDictionary().GetValueOrDefault("fog_motion_links",new Settings()).AsGodotDictionary().Duplicate();if(next.ContainsKey(original)){next[original]=choose.GetItemMetadata((int)index).ToString();var actorDefinition=_definitions.get_definition(Ui<RefCounted>(inspector,"registry"),actor.Get("type_id").AsStringName());if(actorDefinition!=null)_timeline.edit_property(model,actor,actorDefinition,"fog_motion_links",next);}else _timeline.edit_object_property(model,actor,data,definition,key,choose.GetItemMetadata((int)index).ToString());};return true;}
        if(options.GetValueOrDefault("fog_paint",false).AsBool()){bool Active()=>actor.HasMeta("editor_fog_field")&&actor.GetMeta("editor_fog_field").AsGodotObject()==data;void PaintMode(){if(_data.object_get_value(data,"mode",0).AsInt32()!=5)_timeline.edit_object_property(model,actor,data,definition,"mode",5);}var viewport=new Button{Text="Paint in scene viewport",ToggleMode=true,ButtonPressed=Active()};parent.AddChild(viewport);viewport.Toggled+=enabled=>{if(enabled){PaintMode();actor.SetMeta("editor_fog_field",data);}else actor.RemoveMeta("editor_fog_field");};updaters.Add(Callable.From(()=>viewport.SetPressedNoSignal(Active())));var button=new Button{Text="Paint density slices…"};parent.AddChild(button);button.Pressed+=()=>{PaintMode();var editor=GD.Load<GDScript>("res://scripts/actors/fog/fog_painter.gd").New().As<Window>();inspector.AddChild(editor);_fogPainter.setup(editor,inspector,actor,data,definition);editor.PopupCentered(new Vector2I(620,620));};return true;}if(definition.Get("type_id").AsString()=="fog_appearance"&&key.ToString().StartsWith("layer_",System.StringComparison.Ordinal))_fogControls.layer_actions(inspector,actor,data,property,parent);if(options.GetValueOrDefault("natural_material",false).AsBool()){inspector.Call("_add_natural_material_editor",actor,data,definition,property,parent);return true;}if(options.GetValueOrDefault("system_font",false).AsBool()){inspector.Call("_add_object_font",actor,data,definition,property,parent);return true;}if(options.GetValueOrDefault("shader_uniforms",false).AsBool()){inspector.Call("_add_shader_uniforms",actor,data,definition,parent);return true;}if(property.Get("object_type").AsString().Length>0){int depth=inspector.Get("_resource_depth").AsInt32();if(depth>=6){add_label(parent,"Reference depth limit — open the linked resource directly.");return true;}inspector.Set("_resource_depth",depth+1);try{add_nested_object_reference(inspector,actor,data,definition,property,parent);}finally{inspector.Set("_resource_depth",depth);}return true;}return false;
    }
}
